; Questeria, the capital, and the hub. The palace on its terrace to the north with the temple and
; the guildhall either side of it, the plaza and its fountain in the middle, houses to the west and
; the inn and the market to the east, the canal, and the avenue south to the city gate and the old
; road. The harbour's off the west side. Lit, and no fog: everyone knows the capital.

[map]
id = questeria
name = Questeria
world = 300 200
tileset = questeria
size = 84 58
dark = no
fog = no
music = Exploring

[legend]
# = plaza
= = terrace
: = cobble
, = grass
~ = water

[ground]
