; kind id x y, in tiles, then any settings. Exits are rectangles from their top left tile.
[objects]
spawn start 42 34 facing=up
spawn gate 42 55 facing=up
spawn docks 2 26 facing=right
exit road 40 57 w=5 to=road at=start
exit docks 0 23 h=6 to=docks at=city

; The Soul-Bound, as you come up from the harbour.
trigger city-gate 4 22 w=2 h=8 talk=soulbound-city

