; The people. Placeholders: who they are and what they say are mine to write. The ones with
; wander= walk about that many tiles round where they're put.
npc elder 39 32 name="The Elder" sheet=elder facing=down say="Welcome to Questeria. Mind the road past the gate."
npc old-man 46 31 name="An Old Man" sheet=old-man facing=left wander=3 say="The fountain's older than the palace. So they say."
npc child 50 26 name="A Child" sheet=child facing=left wander=5 say="Bet you can't catch me."
npc courier 34 21 name="A Courier" sheet=courier facing=down say="Letters for the guildhall. Mind out."
npc maid 60 20 name="A Maid" sheet=maid facing=down wander=4 say="The guildhall's busy today."
npc pilgrim 22 19 name="A Pilgrim" sheet=pilgrim facing=down say="Listen for the temple bells at dusk."
npc trader 62 35 name="The Trader" sheet=trader facing=down say="Fresh from the coast. Fresh enough."
npc smith 68 35 name="The Smith" sheet=smith facing=down say="Nothing to mend? Lucky you."
npc seamstress 80 35 name="The Seamstress" sheet=seamstress facing=down say="Pink's in this year. It's always in."
npc flower-seller 77 33 name="The Flower Seller" sheet=flower-seller facing=left say="From the palace gardens. Don't tell anyone."
npc porter 72 26 name="A Porter" sheet=porter facing=right wander=4 say="Crates, barrels, crates. All day."
npc weaver 16 34 name="The Weaver" sheet=weaver facing=down say="I spun the palace banners."
npc old-woman 8 37 name="An Old Woman" sheet=old-woman facing=right wander=3 say="Mind the canal. It's deeper than it looks."
npc farmhand 33 48 name="A Farmhand" sheet=farmhand facing=right wander=4 say="First time in the capital? Me too."
npc youth 52 47 name="A Youth" sheet=youth facing=left wander=4 say="There's a barrow up the old road. Haunted, probably."
npc traveller 44 50 name="A Traveller" sheet=traveller facing=down say="Long road out there."
